from metrics import pct_change


def test_normal():
    assert pct_change(200, 250) == 25.0


def test_from_zero_is_none():
    assert pct_change(0, 5) is None


def test_zero_to_zero_is_zero():
    assert pct_change(0, 0) == 0.0


def test_negative_baseline():
    assert pct_change(-100, -50) == -50.0
